package net.battlespades.bot;
import java.util.*;
import static net.battlespades.bot.BotState.Cell;
import static net.battlespades.bot.ProjectSites.Column;

/** Source authored layouts and bounded parametric stairs, rings and walking decks. */
public final class SchematicLibrary {
    private SchematicLibrary(){}
    private static final Map<String,BotSchematic> LIBRARY=load();
    private static Map<String,BotSchematic> load(){var rows=net.battlespades.catalog.SourceCatalog.load("bot-modes").getArray("schematics");var result=new LinkedHashMap<String,BotSchematic>();for(int i=0;i<rows.size();i++){var r=rows.getTable(i);var layers=new ArrayList<List<String>>();var l=r.getArray("layers");for(int h=0;h<l.size();h++)layers.add(net.battlespades.catalog.SourceCatalog.strings(l.getArray(h)));var palette=new LinkedHashMap<String,String>();var chars=r.getArray("palette_chars");var colors=r.getArray("palette_tokens");for(int k=0;k<chars.size();k++)palette.put(chars.getString(k),colors.getString(k));var a=r.getArray("anchor");var o=r.getArray("occupant");Cell occupant=o.isEmpty()?null:new Cell(Math.toIntExact(o.getLong(0)),Math.toIntExact(o.getLong(1)),Math.toIntExact(o.getLong(2)));var s=BotSchematic.authored(r.getString("name"),layers,new Column(Math.toIntExact(a.getLong(0)),Math.toIntExact(a.getLong(1))),palette,net.battlespades.catalog.SourceCatalog.strings(r.getArray("tags")),r.getString("purpose"),r.getString("description"),r.getString("ground_mode"),Math.toIntExact(r.getLong("max_fill")),Math.toIntExact(r.getLong("base_level")),occupant,Math.toIntExact(r.getLong("max_builders")));result.put(s.name(),s);}return Collections.unmodifiableMap(result);}
    public static Map<String,BotSchematic> library(){return LIBRARY;}public static BotSchematic get(String name){return LIBRARY.get(name.toLowerCase(Locale.ROOT));}public static List<BotSchematic> tagged(String tag){return LIBRARY.values().stream().filter(s->s.tags().contains(tag)).toList();}
    public static BotSchematic stair(int height,int width,String name,String color){if(height<1||height>12||width<1||width>3)throw new IllegalArgumentException("Stair dimensions out of range");var layers=new ArrayList<List<String>>();for(int h=0;h<height+3;h++){var rows=new ArrayList<String>();for(int k=height-1;k>=0;k--)rows.add((h<=k?"#":h<=k+3?"_":".").repeat(width));layers.add(rows);}return BotSchematic.authored(name.isEmpty()?"stairs_"+height+"x"+width:name,layers,new Column(width/2,height-1),Map.of("#",color),List.of("traversal","climb","stairs","zombie"),"traversal",height+"-step straight stair","fill",2,0,null,2);}
    public static BotSchematic bridge(int length,String name,String color){if(length<1||length>10)throw new IllegalArgumentException("Bridge length out of range");var rows=new ArrayList<String>();var clear=new ArrayList<String>();for(int i=0;i<length;i++){rows.add("#");clear.add("_");}rows.add(".");clear.add(".");return BotSchematic.authored(name.isEmpty()?"bridge_"+length:name,List.of(rows,clear,clear,clear),new Column(0,length),Map.of("#",color),List.of("traversal","bridge"),"traversal",length+"-cell walking deck","deck",2,-1,null,1);}
    public static BotSchematic ring(int radius,int height,String name,String color,boolean gaps){if(radius<2||radius>8||height<1||height>3)throw new IllegalArgumentException("Ring dimensions out of range");int size=2*radius+1;var rows=new ArrayList<String>();for(int row=0;row<size;row++)rows.add(row==0||row==size-1?"#".repeat(size):gaps&&row==radius?"_"+".".repeat(size-2)+"_":"#"+".".repeat(size-2)+"#");var layers=new ArrayList<List<String>>();for(int h=0;h<height;h++)layers.add(rows);return BotSchematic.authored(name.isEmpty()?"ring_"+radius:name,layers,new Column(radius,radius),Map.of("#",color),List.of("objective","defend","ring","barrier"),"objective","defensive ring radius "+radius,"fill",2,0,null,4);}
}
